import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { CuratedFixture } from '@atlas/github';

/**
 * Curated fixture loader (TRD §10.1.2, §11 demo reliability).
 *
 * Real fixtures are generated by the maintainers' seed script into
 * src/fixtures/<name>.json. This module never creates them; it only reads
 * them from disk next to the source and fails gracefully so the pipeline can
 * fall back to the live GitHub client.
 */

const FIXTURES_DIR = join(dirname(fileURLToPath(import.meta.url)), 'fixtures');

/** Minimal structural check — keeps malformed files from poisoning the demo. */
function isCuratedFixtureShape(value: unknown): value is CuratedFixture {
  if (value === null || typeof value !== 'object') return false;
  const repo = (value as { repository?: unknown }).repository;
  if (repo === null || typeof repo !== 'object') return false;
  const owner = (repo as { owner?: unknown }).owner;
  const name = (repo as { name?: unknown }).name;
  return typeof owner === 'string' && owner.length > 0 && typeof name === 'string' && name.length > 0;
}

export function loadCuratedFixture(name: string): CuratedFixture | null {
  try {
    const filePath = join(FIXTURES_DIR, `${name}.json`);
    const raw = readFileSync(filePath, 'utf8');
    const parsed: unknown = JSON.parse(raw);
    return isCuratedFixtureShape(parsed) ? parsed : null;
  } catch {
    // Missing file, unreadable path, or invalid JSON -> treat as "no fixture".
    return null;
  }
}

export function hasCuratedFixture(name: string): boolean {
  return loadCuratedFixture(name) !== null;
}
